;--------------------------------------------------------------------; нОХЯЮМХЕ: аЕЦСЫЮЪ ЯРПНЙЮ; юБРНП ОНПРЮ: рЮПЮЯНБ л.м.(Mick),2016;--------------------------------------------------------------------Str_reload:		ld	a,(Str_flg_end)		and	a		jr 	z,Str_init		xor	a		ld	(Str_flg_end),a		scf		retStr_init:		ld	hl,Str_addr_text		ld	(Str_addr_work),hl		retStr_init_load:		ld	hl,Str_addr_load		ld	(Str_addr_work),hl		ld	a,1		ld	(Str_flg_end),a		ld	a,(hl)		ret	Str_play:		ld	a,(Str_count_bit)		or	a		call	z,Str_next_symol		retStr_next_symol:		ld	hl,(Str_addr_work)		ld	a,(hl)		and	a		jr	z,Str_reload		ret	c		inc	hl		ld	(Str_addr_work),hl		sub	20h		cp	60h		jr	c, Str_load_data		sub	60hStr_load_data:		ld	l, a		ld	h, 0		ld	de,Str_addr_font		add	hl,hl		add	hl,hl		add	hl,hl		add	hl,de		ld	de,Str_symbol_buf		ldi			ldi			ldi			ldi			ldi			ldi			ldi			ldi			ld	a,8		ld	(Str_count_bit),a		ret	Str_update_symbol:		ld	de, Str_symbol_buf		ld	b,8		ld	hl, 50F5hloc_0_9BA8:		ld	c,0		ld	a,(de)		rlca		ld	(de),a		jr	nc,loc_0_9C03		inc	c		loc_0_9C03:		ld	a,0FEh		and	(hl)		or	c		ld	(hl),a		inc	h		ld	a,h		and	7		jr	nz,loc_0_9BC2		ld	a,l		add	a,20h		ld	l,a		jr	c,loc_0_9BC2		ld	a,h		sub	8		ld	h,aloc_0_9BC2:		inc	de		djnz	loc_0_9BA8		ld	a,(Str_count_bit)		dec	a		ld	(Str_count_bit),a		retStr_draw_symbol:		ld	hl,50F5h		ld	b,8Str_draw_line:		push	hl		and	a		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		dec	l		rl	(hl)		pop	hl		inc	h		ld	a,h		and	7		jr	nz,Str_next_line		ld	a,l		add	a,20h		ld	l,a		ld	c,a		jr	c,Str_next_line		ld	a,h		sub	8		ld	h,aStr_next_line:		djnz	Str_draw_line		ret	Str_symbol_buf:		db 	0,0,0,0,0,0,0,0Str_flg_end:		db 	0Str_count_bit:		db 	0Str_addr_work:		dw 	0Str_addr_load:		db	'  *LOAD*    ',0Str_addr_text:		db 	' 